head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > sortable]<br/>Header Column 을 클릭 또는 더블 클릭하여 데이터를 정렬할지 설정합니다.",
    "validation" : [
        "Header 또는 Body 가 MultiLine 인 경우 같은 Column 위치의 모든 데이터가 함께 정렬됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Body MultiLine + sortable=true 구성)
//  - 한 레코드(Row)를 2 개의 Line 으로 표시
//    Line1 : name(colIndex 0) + age(colIndex 1)
//    Line2 : dept(colIndex 2) + memo(colIndex 3)
//  - header / gBody 에 각각 <w2:row> 를 2 개 두면 한 레코드가 2 Line 으로 렌더됨
//  - sortable=true + showSortableImage=true : Header Column 클릭/더블클릭으로 정렬 수행
//  - 정렬은 바인딩 DataList 의 레코드(Row) 단위로 수행되므로
//    같은 Column 위치의 모든 데이터(한 레코드의 2 Line 전체)가 함께 정렬되어 이동함 (@spec3)
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // MultiLine + sortable 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="Body MultiLine 2 Line(Line1=name·age / Line2=dept·memo) + sortable=true. Header Column 클릭/더블클릭 정렬 시 같은 Column 위치의 2 Line 전체가 레코드 단위로 함께 이동"', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="age" name="age" dataType="text"></w2:column>';
    strDlt += '<w2:column id="dept" name="dept" dataType="text"></w2:column>';
    strDlt += '<w2:column id="memo" name="memo" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // name 기준 정렬 검증용 데이터 (의도적으로 비정렬 상태로 입력)
    let jsonData = [
        { "name": "Mike", "age": "41", "dept": "개발", "memo": "메모M" },
        { "name": "John", "age": "30", "dept": "영업", "memo": "메모J" },
        { "name": "Alice", "age": "25", "dept": "기획", "memo": "메모A" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정 : sortable + showSortableImage (정렬 아이콘 표시) → createCList 공통 함수
    let properties = {
        dataList: "data:dlt_bind",
        sortable: true,
        showSortableImage: true,
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // target 생성 (Body MultiLine : header/gBody 각각 <w2:row> 2 개)
    //  마지막 컬럼 width="*" 로 가로 스크롤 방지
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:520px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="sortable MultiLine 테스트 그리드"></w2:caption>';
    // Header : Line1 = name + age / Line2 = dept + memo
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="hcol_name" value="이름"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol_age" value="나이"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="hrow2">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="hcol_dept" value="부서"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol_memo" value="memo"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    // gBody : Line1 = name(0) + age(1) / Line2 = dept(2) + memo(3)
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="name" dataList="name"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="age" dataList="age"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="brow2">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="dept" dataList="dept"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="memo" dataList="memo"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 정렬 결과 확인 :
//  사용자가 Header Column(예: 이름) 을 클릭/더블클릭하여 정렬을 수행한 뒤 이 버튼을 누르면,
//  바인딩 DataList 의 각 레코드를 순서대로 읽어 같은 Column 위치의 모든 데이터(2 Line 전체)가
//  레코드 단위로 함께 정렬되어 이동했는지 출력함.
//  (정렬 트리거 버튼은 생성하지 않음 — 정렬은 Header 클릭으로 수행)
scwin.btn_checkSortResult_onclick = function (e) {
    let cnt = dlt_bind.getRowCount();
    wf_body_bottom.getObj("scwin").setReturnValue("[현재 정렬 후 레코드 순서] 총 " + cnt + " 건 (각 레코드 = Line1 + Line2 함께 이동)");

    for (let i = 0; i < cnt; i++) {
        // 한 레코드의 Line1(name/age) 과 Line2(dept/memo) 가 같은 레코드에 속해 함께 이동했는지 출력
        let name = dlt_bind.getCellData(i, "name");
        let age = dlt_bind.getCellData(i, "age");
        let dept = dlt_bind.getCellData(i, "dept");
        let memo = dlt_bind.getCellData(i, "memo");
        wf_body_bottom.getObj("scwin").setReturnValue("Row[" + i + "] Line1(name=" + name + ", age=" + age + ") / Line2(dept=" + dept + ", memo=" + memo + ")");
    }
}
